const {execFileSync}=require('node:child_process');const fs=require('node:fs');
const before=JSON.parse(execFileSync('git',['show','HEAD:package.json'],{encoding:'utf8'}));
const after=JSON.parse(fs.readFileSync('package.json','utf8'));
if(before.version===after.version)process.exit(0);
const floor=r=>String(r).replace(/^[\^~]/,'');
const pairs=[[`Bubble ${before.version}`,`Bubble ${after.version}`]];
const policy='repo-policy.json';
for(const[name,to]of Object.entries(after.devDependencies||{})){
  const from=(before.devDependencies||{})[name];const peer=(after.peerDependencies||{})[name];
  if(from&&from!==to&&peer===from)after.peerDependencies[name]=to;
}
fs.writeFileSync('package.json',JSON.stringify(after,null,2)+'\n');
for(const field of ['dependencies','devDependencies','peerDependencies']){
  for(const[name,to]of Object.entries(after[field]||{})){
    const from=(before[field]||{})[name];const m=/^@kubohiroya\/turbowarp-(.+)$/.exec(name);
    if(!m||!from||from===to)continue;
    const title=({'svg-text':'SVG Text'})[m[1]]??m[1].split('-').map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
    if(!pairs.some(q=>q[0]===`${title} ${floor(from)}`))pairs.push([`${title} ${floor(from)}`,`${title} ${floor(to)}`],[`${name}@${floor(from)}`,`${name}@${floor(to)}`]);
    if(fs.existsSync(policy)){
      const t=fs.readFileSync(policy,'utf8');const o=`"${name}": "${floor(from)}"`;
      if(t.includes(o))fs.writeFileSync(policy,t.split(o).join(`"${name}": "${floor(to)}"`));
    }
  }
}
for(const f of ['README.md','README.ja.md','docs/block-manual.md','docs/block-manual.ja.md','docs/index.html','docs/ja/index.html']){
  let t=fs.readFileSync(f,'utf8');for(const[o,n]of pairs)t=t.split(o).join(n);fs.writeFileSync(f,t);
}
const f='src/extension.ts',t=fs.readFileSync(f,'utf8');
const old=`EXTENSION_VERSION = "${before.version}"`,next=`EXTENSION_VERSION = "${after.version}"`;
if(!t.includes(next)){
  const n=t.split(old).length-1;if(n!==1)throw new Error(`${f}: expected one ${old}, found ${n}`);
  fs.writeFileSync(f,t.replace(old,next));
}
console.log('bubble version text:',pairs.map(p=>p.join(' -> ')).join(', '));
